const updReturning = " RETURNING \"id\", \"created_at\", \"updated_at\", \"instance_id\", \"definition_id\", \"organization_id\", \"node_id\", \"iteration_id\", \"type\", \"status\", \"locked_by\", \"lock_expires\", \"payload\", \"retries\", \"max_retries\", \"repeats_remaining\", \"next_run_at\", \"last_error\", \"deleted_at\""

// Masks reports how many distinct UPDATE shapes have compiled.
func Masks() int { return updCache.Masks() }

// Guarded increments. Each takes an expression bit above every
// column's, so it is a statement key of its own and the loops over
// the columns pass it by.
const (
	guardRetries uint64 = 1 << (nUpdatable + 0)
)

// guardFrags adds one to a counter when another column, as the row
// stands before the write, equals the bound value.
var guardFrags = [1]runtime.Frag{
	{A: "\"retries\" = \"retries\" + CASE WHEN \"status\" = $", B: " THEN 1 ELSE 0 END"}, // retries + 1 when status matches
}

// withGuards appends the guarded increments expr carries, in order.
func withGuards(expr uint64, set []runtime.Frag) []runtime.Frag {
	for j := range guardFrags {
		if expr&(1<<uint(nUpdatable+j)) != 0 {
			set = append(set, guardFrags[j])
		}
	}
	return set
}

// guardArgs appends the values the guarded increments compare with,
// in the order withGuards writes them.
func (m Mut) guardArgs(args []any) []any {
	if m.expr&guardRetries != 0 {
		args = append(args, m.whenRetries)
	}
	return args
}

// Mut is a row staged for update: the values, plus which of them were
// actually assigned. An UPDATE writes the assigned ones and no others,
// so a read-modify-write cannot clobber a column it never looked at.
type Mut struct {
	row   Row
	dirty uint64
	expr  uint64
	// whenRetries is what IncRetriesWhenStatus compares status with.
	whenRetries string
}

// Mutate stages a row read from the database.
func Mutate(r Row) Mut { return Mut{row: r} }

// MutateKey stages an update addressed by primary key alone, for a
// caller that has not read the row.
//
// Only assigned columns are written, so the fields left zero here are
// never referenced — the staged row is an address, not a value. It
// pairs with the server-side setters: one statement, no prior read.
func MutateKey(iD [16]byte) Mut {
	return Mut{row: Row{
		ID: iD,
	}}
}

// Row returns the staged values.
func (m Mut) Row() Row { return m.row }

// Dirty reports the columns assigned a bound value.
func (m Mut) Dirty() uint64 { return m.dirty }

// Expr reports the columns assigned a server-side expression. Together
// with Dirty it is the statement key: the same column written two ways
// is two different statements, and one cannot bind the other's args.
func (m Mut) Expr() uint64 { return m.expr }

// key is this Mut's statement identity.
func (m Mut) key() runtime.MaskKey {
	return runtime.MaskKey{Dirty: m.dirty, Expr: m.expr}
}

