// Ins stages a new row, with a setter for every insertable column. A column
// left unset is absent from the statement, so the database default applies;
// a zero value that was set is written.
type Ins struct {
	row Row
	set uint64

	// conflict is the upsert target, as a bit per unique-constraint
	// column set. Zero means a plain insert, and a duplicate is an error
	// — which is the right default: silently updating a row you meant to
	// create is a data-loss bug that looks like success.
	conflict uint8

	// add marks the assigned columns an upsert ACCUMULATES into rather
	// than overwrites. Part of the statement key, beside the mask.
	add uint64
}

// Create stages a new row.
func Create() Ins { return Ins{} }

// Assigned reports the mask, which is also the statement key.
func (n Ins) Assigned() uint64 { return n.set }

// insertArgs appends the values n assigns, in column order.
func (n *Ins) insertArgs(args []any) []any {
	for i := 0; i < nInsertable; i++ {
		if n.set&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, n.row.ID)
		case 1:
			args = append(args, n.row.CreatedAt)
		case 2:
			args = append(args, n.row.UpdatedAt)
		case 3:
			args = append(args, n.row.InstanceID)
		case 4:
			args = append(args, n.row.DefinitionID)
		case 5:
			args = append(args, n.row.OrganizationID.Arg())
		case 6:
			args = append(args, n.row.NodeID)
		case 7:
			args = append(args, n.row.IterationID.Arg())
		case 8:
			args = append(args, n.row.Type)
		case 9:
			args = append(args, n.row.Status)
		case 10:
			args = append(args, n.row.LockedBy.Arg())
		case 11:
			args = append(args, n.row.LockExpires.Arg())
		case 12:
			args = append(args, n.row.Payload.OrNull())
		case 13:
			args = append(args, n.row.Retries)
		case 14:
			args = append(args, n.row.MaxRetries)
		case 15:
			args = append(args, n.row.RepeatsRemaining)
		case 16:
			args = append(args, n.row.NextRunAt)
		case 17:
			args = append(args, n.row.LastError.Arg())
		case 18:
			args = append(args, n.row.DeletedAt.Arg())
		}
	}
	return args
}

